struct gate {                       /* one gate per boundary */
    int (*allowed)(const struct req *, const struct id *);
    struct gate *next;              /* the inner gate; NULL at the resource */
};
static int handle(struct gate *g, struct req *r, struct id *id) {
    if (!g->allowed(r, id)) { audit_deny(r, id); return DENIED; }   /* fail closed */
    audit_allow(r, id);
    if (!g->next) return serve(r, id);          /* innermost: the resource */
    return handle(g->next, r, id);              /* delegate inward, unmerged */
}
